        [@"Početak proslave"] = new[] { @"Početak proslave", @"Početak proslave", @"Početak proslave", @"Začetek praznovanja", @"Beginn der Feier", @"Start of the celebration" },
        [@"Sa velikom radošću pozivamo vas da s nama podijelite najljepši dan našeg života. Vaše prisustvo učiniće ga potpunim."] = new[] { @"Sa velikom radošću pozivamo vas da s nama podelite najlepši dan našeg života. Vaše prisustvo učiniće ga potpunim.", @"Sa velikom radošću pozivamo vas da s nama podijelite najljepši dan našeg života. Vaše prisustvo učiniće ga potpunim.", @"Sa velikom radošću pozivamo vas da s nama podijelite najljepši dan našeg života. Vaše prisustvo učiniće ga potpunim.", @"Z veliko radostjo vas vabimo, da z nami delite najlepši dan našega življenja. Vaša prisotnost ga bo naredila popolnega.", @"Mit großer Freude laden wir Sie ein, den schönsten Tag unseres Lebens mit uns zu teilen. Ihre Anwesenheit macht ihn vollkommen.", @"With great joy we invite you to share the most beautiful day of our lives with us. Your presence will make it complete." },
        [@"Ljubav je najljepša kad se dijeli s onima koje volimo. Zato vas pozivamo da nam se pridružite na dan kada postajemo jedno."] = new[] { @"Ljubav je najlepša kad se deli s onima koje volimo. Zato vas pozivamo da nam se pridružite na dan kada postajemo jedno.", @"Ljubav je najljepša kad se dijeli s onima koje volimo. Zato vas pozivamo da nam se pridružite na dan kada postajemo jedno.", @"Ljubav je najljepša kad se dijeli s onima koje volimo. Zato vas pozivamo da nam se pridružite na dan kada postajemo jedno.", @"Ljubezen je najlepša, kadar jo delimo z ljudmi, ki jih imamo radi. Zato vas vabimo, da se nam pridružite na dan, ko postanemo eno.", @"Liebe ist am schönsten, wenn man sie mit den Menschen teilt, die man liebt. Deshalb laden wir Sie ein, den Tag mit uns zu feiern, an dem wir eins werden.", @"Love is most beautiful when shared with those we love. That's why we invite you to join us on the day we become one." },
        [@"Naša priča dobija novo poglavlje i želimo da ga zajedno počnemo s vama. Radujemo se vašem dolasku."] = new[] { @"Naša priča dobija novo poglavlje i želimo da ga zajedno počnemo s vama. Radujemo se vašem dolasku.", @"Naša priča dobija novo poglavlje i želimo da ga zajedno počnemo s vama. Radujemo se vašem dolasku.", @"Naša priča dobija novo poglavlje i želimo da ga zajedno počnemo s vama. Radujemo se vašem dolasku.", @"Naša zgodba dobiva novo poglavje in želimo ga začeti skupaj z vami. Veselimo se vašega prihoda.", @"Unsere Geschichte bekommt ein neues Kapitel, und wir möchten es gemeinsam mit Ihnen beginnen. Wir freuen uns auf Ihr Kommen.", @"Our story is getting a new chapter and we want to begin it together with you. We look forward to your arrival." },
        [@"Sa radošću vas pozivamo da s nama proslavite krštenje našeg djeteta i podijelite ovaj blagoslovljeni dan."] = new[] { @"Sa radošću vas pozivamo da s nama proslavite krštenje našeg deteta i podelite ovaj blagoslovljeni dan.", @"Sa radošću vas pozivamo da s nama proslavite krštenje našeg djeteta i podijelite ovaj blagoslovljeni dan.", @"Sa radošću vas pozivamo da s nama proslavite krštenje našeg djeteta i podijelite ovaj blagoslovljeni dan.", @"Z veseljem vas vabimo, da z nami praznujete krst našega otroka in delite ta blagoslovljeni dan.", @"Mit Freude laden wir Sie ein, die Taufe unseres Kindes mit uns zu feiern und diesen gesegneten Tag zu teilen.", @"We joyfully invite you to celebrate the christening of our child with us and to share this blessed day." },
        [@"Veliku radost želimo podijeliti s vama. Pozivamo vas na krštenje našeg malog anđela."] = new[] { @"Veliku radost želimo podeliti s vama. Pozivamo vas na krštenje našeg malog anđela.", @"Veliku radost želimo podijeliti s vama. Pozivamo vas na krštenje našeg malog anđela.", @"Veliku radost želimo podijeliti s vama. Pozivamo vas na krštenje našeg malog anđela.", @"Veliko veselje želimo deliti z vami. Vabimo vas na krst našega malega angela.", @"Unsere große Freude möchten wir mit Ihnen teilen. Wir laden Sie zur Taufe unseres kleinen Engels ein.", @"We want to share our great joy with you. We invite you to the christening of our little angel." },
        [@"Vaše prisustvo učiniće ovaj svečani dan još ljepšim. Radujemo se zajedničkom slavlju."] = new[] { @"Vaše prisustvo učiniće ovaj svečani dan još lepšim. Radujemo se zajedničkom slavlju.", @"Vaše prisustvo učiniće ovaj svečani dan još ljepšim. Radujemo se zajedničkom slavlju.", @"Vaše prisustvo učiniće ovaj svečani dan još ljepšim. Radujemo se zajedničkom slavlju.", @"Vaša prisotnost bo ta slavnostni dan naredila še lepši. Veselimo se skupnega slavja.", @"Ihre Anwesenheit macht diesen festlichen Tag noch schöner. Wir freuen uns auf die gemeinsame Feier.", @"Your presence will make this festive day even more beautiful. We look forward to celebrating together." },
        [@"Još jedna godina, još jedan razlog za slavlje! Pozivamo vas da s nama proslavite ovaj poseban dan."] = new[] { @"Još jedna godina, još jedan razlog za slavlje! Pozivamo vas da s nama proslavite ovaj poseban dan.", @"Još jedna godina, još jedan razlog za slavlje! Pozivamo vas da s nama proslavite ovaj poseban dan.", @"Još jedna godina, još jedan razlog za slavlje! Pozivamo vas da s nama proslavite ovaj poseban dan.", @"Še eno leto, še en razlog za praznovanje! Vabimo vas, da z nami praznujete ta poseben dan.", @"Ein weiteres Jahr, ein weiterer Grund zu feiern! Wir laden Sie ein, diesen besonderen Tag mit uns zu feiern.", @"Another year, another reason to celebrate! We invite you to celebrate this special day with us." },
        [@"Dobro društvo je najljepši poklon. Dođite da zajedno napravimo nezaboravnu proslavu."] = new[] { @"Dobro društvo je najlepši poklon. Dođite da zajedno napravimo nezaboravnu proslavu.", @"Dobro društvo je najljepši poklon. Dođite da zajedno napravimo nezaboravnu proslavu.", @"Dobro društvo je najljepši poklon. Dođite da zajedno napravimo nezaboravnu proslavu.", @"Dobra družba je najlepše darilo. Pridite, da skupaj naredimo nepozabno praznovanje.", @"Gute Gesellschaft ist das schönste Geschenk. Kommen Sie, damit wir gemeinsam eine unvergessliche Feier gestalten.", @"Good company is the best gift. Come and let's make an unforgettable celebration together." },
        [@"Spremni smo za muziku, smijeh i dobru zabavu. Čekamo vas!"] = new[] { @"Spremni smo za muziku, smeh i dobru zabavu. Čekamo vas!", @"Spremni smo za glazbu, smijeh i dobru zabavu. Čekamo vas!", @"Spremni smo za muziku, smijeh i dobru zabavu. Čekamo vas!", @"Pripravljeni smo na glasbo, smeh in dobro zabavo. Čakamo vas!", @"Wir sind bereit für Musik, Lachen und gute Unterhaltung. Wir warten auf Sie!", @"We're ready for music, laughter and great fun. We're waiting for you!" },
        [@"Godine su prošle, a ljubav je ostala. Pozivamo vas da s nama proslavite našu godišnjicu."] = new[] { @"Godine su prošle, a ljubav je ostala. Pozivamo vas da s nama proslavite našu godišnjicu.", @"Godine su prošle, a ljubav je ostala. Pozivamo vas da s nama proslavite našu godišnjicu.", @"Godine su prošle, a ljubav je ostala. Pozivamo vas da s nama proslavite našu godišnjicu.", @"Leta so minila, ljubezen pa je ostala. Vabimo vas, da z nami praznujete našo obletnico.", @"Die Jahre sind vergangen, die Liebe ist geblieben. Wir laden Sie ein, unser Jubiläum mit uns zu feiern.", @"The years have passed, but love remains. We invite you to celebrate our anniversary with us." },
        [@"Zahvalni smo na svakom zajedničkom danu i želimo da ovaj podijelimo s vama."] = new[] { @"Zahvalni smo na svakom zajedničkom danu i želimo da ovaj podelimo s vama.", @"Zahvalni smo na svakom zajedničkom danu i želimo da ovaj podijelimo s vama.", @"Zahvalni smo na svakom zajedničkom danu i želimo da ovaj podijelimo s vama.", @"Hvaležni smo za vsak skupni dan in želimo ta dan deliti z vami.", @"Wir sind dankbar für jeden gemeinsamen Tag und möchten diesen mit Ihnen teilen.", @"We are grateful for every day together and want to share this one with you." },
        [@"Vaše prisustvo učinilo bi ovu proslavu savršenom."] = new[] { @"Vaše prisustvo učinilo bi ovu proslavu savršenom.", @"Vaše prisustvo učinilo bi ovu proslavu savršenom.", @"Vaše prisustvo učinilo bi ovu proslavu savršenom.", @"Vaša prisotnost bi to praznovanje naredila popolno.", @"Ihre Anwesenheit würde diese Feier perfekt machen.", @"Your presence would make this celebration perfect." },
        [@"Sa zadovoljstvom vas pozivamo da nam se pridružite i s nama proslavite ovaj poseban dan."] = new[] { @"Sa zadovoljstvom vas pozivamo da nam se pridružite i s nama proslavite ovaj poseban dan.", @"Sa zadovoljstvom vas pozivamo da nam se pridružite i s nama proslavite ovaj poseban dan.", @"Sa zadovoljstvom vas pozivamo da nam se pridružite i s nama proslavite ovaj poseban dan.", @"Z veseljem vas vabimo, da se nam pridružite in z nami praznujete ta poseben dan.", @"Wir laden Sie gerne ein, sich uns anzuschließen und diesen besonderen Tag mit uns zu feiern.", @"We are pleased to invite you to join us and celebrate this special day with us." },
        [@"Radujemo se što ćemo ovaj trenutak podijeliti s vama."] = new[] { @"Radujemo se što ćemo ovaj trenutak podeliti s vama.", @"Radujemo se što ćemo ovaj trenutak podijeliti s vama.", @"Radujemo se što ćemo ovaj trenutak podijeliti s vama.", @"Veseli smo, da bomo ta trenutek delili z vami.", @"Wir freuen uns, diesen Moment mit Ihnen zu teilen.", @"We are happy to share this moment with you." },
